168	    payload = {app:a.app,monitor:prepared.row,first_check:prepared.first}; notCreated = [row.type];
169	  } else if(tool === "provision_app") {
170	    const a = inputs.provision_app.parse(input); const url = normalizeAppUrl(a.url);
171	    // URL parsing and address refusal happen even for an existing app.
172	    const appId = `app_${"0".repeat(24)}`;
173	    const drafts = [agentMonitorRow({ request_id:a.request_id,app:appId,type:"http",target:url,config:{},name:"Website" })];
174	    const skipped: {item:string;reason:string}[] = [];
175	    for(const cron of a.crons_from ?? []) drafts.push(agentMonitorRow({request_id:a.request_id,app:appId,type:"heartbeat",name:cron.name,target:cron.name,config:{schedule:cron.schedule,tz:cron.tz}}));
176	    if(a.supabase_url && a.supabase_key) drafts.push(agentMonitorRow({request_id:a.request_id,app:appId,type:"supabase",target:a.supabase_url,config:{key:a.supabase_key}}));
177	    else if(a.supabase_url || a.supabase_key) skipped.push({item:"supabase",reason:"Provide both supabase_url and its publishable key to create the health check."});
178	    if(a.stripe_key && a.stripe_endpoints?.length) drafts.push(agentMonitorRow({request_id:a.request_id,app:appId,type:"stripe",target:"https://api.stripe.com",config:{key:a.stripe_key,endpoints:a.stripe_endpoints}}));
179	    else if(a.stripe_key || a.stripe_endpoints) skipped.push({item:"stripe",reason:"Provide both a restricted key and the webhook endpoint ids to watch."});
180	    if(a.mcp_url) skipped.push({item:"mcp",reason:"MCP server monitors are Coming soon."});
181	    if(a.status_domain) skipped.push({item:"status_domain",reason:"Custom-domain setup belongs to the separate status-edge stage. The standard status page is available."});
182	    await budget();
183	    const prepared = await Promise.all(drafts.map(row=>prepareMonitor(p,row)));
184	    // The transaction chooses an unused default while holding the workspace lock.
185	    // An explicit name stays exact so a collision is a refusal, not a silent rename.
